<?php
/** Portable file catalogs, native preservation and safe fallback without Drupal writes. */
$lab=dirname(__DIR__,3);require $lab.'/integration/vendor/autoload.php';
foreach(['Catalog','Translator']as$class){require_once dirname(__DIR__).'/web/modules/custom/labdoo_translations/src/'.$class.'.php';}
use Drupal\labdoo_translations\Catalog;
use Drupal\labdoo_translations\Translator;
$directory=sys_get_temp_dir().'/labdoo-translations-test-'.bin2hex(random_bytes(6));mkdir($directory,0700);
$strings=['Hello @name'=>'','Open'=>'verb','Read <a href=":url">more</a>'=>''];$source=[];foreach($strings as$text=>$context){$source[Catalog::id($text,$context)]=['source'=>$text,'context'=>$context];}
$write=static function($file,$value)use($directory){file_put_contents($directory.'/'.$file,json_encode($value,JSON_THROW_ON_ERROR));};
$write('source.json',['strings'=>$source]);$write('es.json',['language'=>'es','translations'=>[Catalog::id('Hello @name')=>'Hola @name',Catalog::id('Open','verb')=>'Abrir',Catalog::id('Read <a href=":url">more</a>')=>'Leer <a href=":url">más</a>']]);
$catalog=new Catalog($directory);$passed=[];$assert=static function($ok,$message){if(!$ok){throw new LogicException($message);}};
try{
 $assert(Catalog::validTranslation("1 place\x03@count places","1 miejsce\x03@count miejsca\x03@count miejsc")&&Catalog::validTranslation("1\x03@count",'@count')&&Catalog::validTranslation("1 place\x03@count places","@count emplacement\x03@count emplacements")&&!Catalog::validTranslation("1\x03@count","1\x03@other")&&!Catalog::validTranslation("@name: 1\x03@name: @count",'@count'),'Language-specific plural variants rejected or placeholders lost.');$passed[]='one, two and three plural variants preserve tokens per source variant';
 $assert(Catalog::validTranslation("Yes: Yes\nNo: No\n","Yes: Sí\nNo: No\n")&&!Catalog::validTranslation("Yes: Yes\nNo: No\n","true: Sí\nfalse: No\n")&&!Catalog::validTranslation("field:\n  '#type': textfield\n  '#title': Name\n","field:\n  '#title': Nombre\n"),'YAML operational keys or schema lost.');$passed[]='YAML preserves Symfony key types and complete form structure';
 $assert(Catalog::validTranslation('< Previous','< Anterior')&&Catalog::validTranslation('< Previous','< 前へ')&&Catalog::validTranslation('{Empty}','{Vacío}')&&!Catalog::validTranslation('{username}','{nombre}'),'Visible labels mistaken for markup or tokens.');$passed[]='navigation text and Webform empty label translate without weakening real tokens';
 $assert($catalog->lookup('es','Hello @name')==='Hola @name','Exact context-free lookup failed.');$passed[]='portable source/language JSON resolves exact source IDs';
 $assert($catalog->lookup('es','Open','verb')==='Abrir'&&$catalog->lookup('es','Open')===NULL,'Context collision.');$passed[]='context is part of the stable source key';
 $assert($catalog->lookup('es','Uncatalogued')===NULL&&$catalog->lookup('de','Hello @name')===NULL&&$catalog->lookup('../es','Hello @name')===NULL,'Unsafe or missing fallback.');$passed[]='missing source/language and path traversal fall back without writes';
 $before=$catalog->version('es');$write('es.json',['language'=>'es','translations'=>[Catalog::id('Hello @name')=>'Saludos @name']]);$assert($catalog->lookup('es','Hello @name')==='Hola @name','Request cache changed unexpectedly.');$catalog->reset();$assert($catalog->lookup('es','Hello @name')==='Saludos @name'&&$catalog->version('es')!==$before,'Catalog refresh did not change fingerprint.');$passed[]='request-local caching resets with catalog language/source fingerprint';
 $assert(!Catalog::validTranslation('Hello @name','Hola')&&!Catalog::validTranslation('Read <a href=":url">more</a>','Leer <a href="javascript:alert(1)">más</a>')&&!Catalog::validTranslation('[site:name]','[site:other]'),'Protected values changed.');$passed[]='placeholders, Drupal tokens and link targets cannot be altered';
 $assert(!Catalog::validTranslation('@name','@name @name')&&!Catalog::validTranslation('%count','%city')&&!Catalog::validTranslation('Amount %1$s','Montant %1$d'),'Duplicate or renamed placeholders accepted.');$passed[]='placeholder multiplicity, named placeholders and printf formats remain intact';
 $assert(Catalog::validTranslation('<img src="a.png" alt="School"/>',"<img src='a.png' alt='École'>")&&!Catalog::validTranslation('<span class="original">Hello</span>','<span class="changed">Hola</span>'),'Fixed attributes changed or accessible labels rejected.');$passed[]='fixed markup attributes are preserved while accessibility labels can translate';
 $assert(!Catalog::validTranslation('</div><script>safe()</script>','</div><script>changed()</script>')&&!Catalog::validTranslation('Hello',"Bad\xFF"),'Malformed markup escaped validation or invalid UTF8 accepted.');$passed[]='fragment boundary tricks and invalid Unicode cannot bypass safe fallback';
 $fileTranslator=new Translator($catalog);$assert($fileTranslator->getStringTranslation('es','Hello @name','')==='Saludos @name','Initial provider text missing.');$write('es.json',['language'=>'es','translations'=>[Catalog::id('Hello @name')=>'Otra @name']]);$catalog->reset();$assert($fileTranslator->getStringTranslation('es','Hello @name','')==='Otra @name','Provider cache ignored changed catalog fingerprint.');$passed[]='translator cache follows catalog version changes after independent catalog reset';
 $native=new class{public int$count=0;public function findTranslation(array$conditions){$this->count++;return new class{public function getString(){return'Saludo nativo @name';}};}};
 $translator=new Translator($catalog,$native);$assert($translator->getStringTranslation('es','Hello @name','')==='Saludo nativo @name','Existing native translation overwritten.');$translator->getStringTranslation('es','Hello @name','');$assert($native->count===1,'Native lookup not cached.');$passed[]='valid native Locale text wins and is read only once per request';
 $assert($translator->getStringTranslation('es','Uncatalogued','')===FALSE&&$native->count===1,'Uncatalogued source registered or intercepted.');$passed[]='uncatalogued strings continue through Drupal providers without native registration';
 $write('es.json',['language'=>'de','translations'=>[Catalog::id('Hello @name')=>'Incorrect @name']]);$catalog->reset();$assert($catalog->lookup('es','Hello @name')===NULL&&!empty($catalog->errors()),'Mismatched language accepted.');$passed[]='incorrect language metadata fails safely';
 file_put_contents($directory.'/es.json','{broken');$catalog->reset();$assert($catalog->lookup('es','Hello @name')===NULL&&!empty($catalog->errors()),'Malformed JSON crashed fallback.');$passed[]='malformed catalogs report safe errors and keep fallback available';
 $write('es.json',['language'=>'es','translations'=>[Catalog::id('Hello @name')=>'Invalid missing placeholder']]);$catalog->reset();$assert($catalog->lookup('es','Hello @name')===NULL&&!empty($catalog->errors()),'Invalid translated placeholder accepted.');$passed[]='invalid translated entries do not suppress native/source fallback';
 $source['forged-id']=['source'=>'Forged source','context'=>''];$write('source.json',['strings'=>$source]);$catalog->reset();$assert($catalog->lookup('es','Forged source')===NULL&&!empty($catalog->errors()),'Forged source identity accepted.');$passed[]='forged IDs cannot redirect lookups to a different source';
 $pluralSource="1 place\x03@count places";$pluralCatalog="1 miejsce\x03@count miejsca\x03@count miejsc";
 $write('source.json',['strings'=>[Catalog::id($pluralSource)=>['source'=>$pluralSource,'context'=>'']]]);
 $write('pl.json',['language'=>'pl','translations'=>[Catalog::id($pluralSource)=>$pluralCatalog]]);
 $pluralNative=new class{public string$value="1 natywne miejsce\x03@count natywnych miejsc";public function findTranslation(array$conditions){return new class($this->value){public function __construct(private string$value){}public function getString(){return$this->value;}};}};
 $pluralProvider=new Translator(new Catalog($directory),$pluralNative);
 $assert($pluralProvider->getStringTranslation('pl',$pluralSource,'')===$pluralCatalog,'Incomplete two-form native plural suppressed complete Polish catalog.');$passed[]='three-form Polish catalog replaces incomplete two-form native Locale translation';
 $pluralNative->value="1 natywne miejsce\x03@count natywne miejsca\x03@count natywnych miejsc";$pluralProvider->reset();
 $assert($pluralProvider->getStringTranslation('pl',$pluralSource,'')===$pluralNative->value,'Valid native three-form Polish plural was overwritten.');$passed[]='valid three-form native Locale plural remains preferred over portable catalog';
 echo json_encode(['passed'=>count($passed),'cases'=>$passed],JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR)."\n";
}
finally{foreach(glob($directory.'/*')as$file){unlink($file);}rmdir($directory);}
